const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)), rnd=(a,b)=>a+Math.random()*(b-a);
const STANDING_EYE_HEIGHT=1.7,CROUCHING_EYE_HEIGHT=.95,WALK_SPEED=7.488,CROUCH_SPEED=3.432;
