const solid=(x,z,w,d,h,c=palettes.wall)=>{walls.push({x,z,w,d,h});box(staticData,x,h/2,z,w,h,d,c);};
function container(x,z,w=4,d=8,c=palettes.metal){solid(x,z,w,d,3,c);box(staticData,x,3.05,z,w+.16,.15,d+.16,palettes.dark);for(let i=-d/2+.25;i<d/2;i+=.65){for(let sx of [-1,1])box(staticData,x+sx*(w/2+.035),1.48,z+i,.07,2.8,.07,palettes.dark);}box(staticData,x,2.55,z+d/2+.025,w*.64,.15,.03,palettes.lime,1);box(staticData,x,1.35,z+d/2+.06,.05,2.4,.05,palettes.dark);}
