function mapAsset(key,x,z,size=1,yaw=0,y=0){
 const model=MAP_ASSET_MODELS[key];if(!model)return;
 const vertices=model.vertices,cs=Math.cos(yaw),sn=Math.sin(yaw);
 for(let i=0;i<vertices.length;i+=10){
  const px=vertices[i]*size,pz=vertices[i+2]*size,nx=vertices[i+3],nz=vertices[i+5];
  staticData.push(x+px*cs+pz*sn,y+vertices[i+1]*size,z+pz*cs-px*sn,nx*cs+nz*sn,vertices[i+4],nz*cs-nx*sn,vertices[i+6],vertices[i+7],vertices[i+8],vertices[i+9]);
 }
}
function mapProp(key,x,z,size=1,yaw=0,collides=true){
 const model=MAP_ASSET_MODELS[key];if(!model)return;
 mapAsset(key,x,z,size,yaw);
 if(collides){
  const b=model.bounds,cs=Math.abs(Math.cos(yaw)),sn=Math.abs(Math.sin(yaw));
  walls.push({x,z,w:(b.max[0]-b.min[0])*size*cs+(b.max[2]-b.min[2])*size*sn,d:(b.max[2]-b.min[2])*size*cs+(b.max[0]-b.min[0])*size*sn,h:b.max[1]*size});
 }
}
