   mapPolishRect(out,wall.x,wall.h*.68,z+side*.016,1.25,.72,dark,0,yaw,true);
   mapPolishNumber(out,wall.x,wall.h*.68,z+side*.024,String(number).padStart(2,'0'),.49,accent,yaw);
