function activateMap(id){
 currentMap=MAP_DEFINITIONS[id]||MAP_DEFINITIONS.training;
 let scene=mapSceneCache.get(currentMap.id);
 if(!scene){
  staticData.length=0;walls.length=0;
  if(currentMap.id==='training')buildTraining();else if(currentMap.id==='harbor')buildHarbor();else if(currentMap.id==='ruins')buildRuins();else buildOutpost();
  polishMapScene(currentMap.id,staticData,walls);
  scene={arena:mesh(staticData),walls:walls.slice()};mapSceneCache.set(currentMap.id,scene);
 }
 arena=scene.arena;walls.length=0;walls.push(...scene.walls);
 resetEnemyNavigation();
 $('mapSelect').value=currentMap.id;$('mapTitle').textContent=currentMap.name;$('mapDescription').textContent=currentMap.description;$('mapHudName').textContent=currentMap.name;
}

activateMap('training');
const dynamic={buffer:gl.createBuffer(),count:0,capacity:0};
// Reuse effect storage rather than allocating large vertex arrays every frame.
const effectData={values:new Float32Array(65536),length:0,push(x,y,z,nx,ny,nz,r,g,b,e){const i=this.length;if(i+10>this.values.length){const grown=new Float32Array(this.values.length*2);grown.set(this.values);this.values=grown;}const a=this.values;a[i]=x;a[i+1]=y;a[i+2]=z;a[i+3]=nx;a[i+4]=ny;a[i+5]=nz;a[i+6]=r;a[i+7]=g;a[i+8]=b;a[i+9]=e;this.length=i+10;}};
function drawEffects(vp,eye){if(!effectData.length)return;gl.bindBuffer(gl.ARRAY_BUFFER,dynamic.buffer);if(dynamic.capacity<effectData.values.byteLength){dynamic.capacity=effectData.values.byteLength;gl.bufferData(gl.ARRAY_BUFFER,dynamic.capacity,gl.DYNAMIC_DRAW);}gl.bufferSubData(gl.ARRAY_BUFFER,0,effectData.values.subarray(0,effectData.length));dynamic.count=effectData.length/10;draw(dynamic,vp,eye);}
