const HEAD_HIT_SAMPLE_RATE=48000,HEAD_HIT_CHANNELS=1;
const HEAD_HIT_PCM_BASE64='';
const HEAD_KILL_SAMPLE_RATE=48000,HEAD_KILL_CHANNELS=2;
const HEAD_KILL_PCM_BASE64='';
let combatAudioCache=null,combatAudioResumePending=null;

function combatBuildRecordedPCM(context,encoded,rate,channels){
  const packed=atob(encoded),count=packed.length/(2*channels);
  const buffer=context.createBuffer(channels,count,rate);
  for(let channel=0;channel<channels;channel++){
    const samples=buffer.getChannelData(channel);
    for(let i=0;i<count;i++){
      const offset=(i*channels+channel)*2;
      let value=packed.charCodeAt(offset)|(packed.charCodeAt(offset+1)<<8);
      if(value&0x8000)value-=65536;
      samples[i]=value/32768;
    }
  }
  return buffer;
}

function combatBuildRecordedAK(context){
  return combatBuildRecordedPCM(context,AK_SHOT_PCM_BASE64,AK_SHOT_SAMPLE_RATE,AK_SHOT_CHANNELS);
}

function combatBuildBuffer(context,kind){
  if(kind==='shot')return combatBuildRecordedAK(context);
  if(kind==='head')return combatBuildRecordedPCM(context,HEAD_HIT_PCM_BASE64,HEAD_HIT_SAMPLE_RATE,HEAD_HIT_CHANNELS);
  return combatBuildRecordedPCM(context,HEAD_KILL_PCM_BASE64,HEAD_KILL_SAMPLE_RATE,HEAD_KILL_CHANNELS);
}

function prepareCombatAudio(){
  if(!sound)return false;
  try{
    const AudioContextClass=window.AudioContext||window.webkitAudioContext;
    if(!AudioContextClass)return false;
    if(!audioCtx||audioCtx.state==='closed')audioCtx=new AudioContextClass();
    if(audioCtx.state==='suspended'&&combatAudioResumePending!==audioCtx){
      const context=audioCtx;
      combatAudioResumePending=context;
      const resumed=context.resume();
      if(resumed&&typeof resumed.then==='function'){
        const finish=()=>{if(combatAudioResumePending===context)combatAudioResumePending=null;};
        resumed.then(finish,finish);
      }else combatAudioResumePending=null;
    }
    if(!combatAudioCache||combatAudioCache.context!==audioCtx){
      if(combatAudioCache)try{combatAudioCache.bus.disconnect();}catch{}
      const bus=audioCtx.createGain();
      // Headroom for an automatic-fire tail, a simultaneous headshot and existing UI sounds.
      bus.gain.value=.80;bus.connect(audioCtx.destination);
      combatAudioCache={context:audioCtx,bus,shot:combatBuildBuffer(audioCtx,'shot'),head:combatBuildBuffer(audioCtx,'head'),headKill:combatBuildBuffer(audioCtx,'headKill')};
    }
    return true;
  }catch{
    combatAudioResumePending=null;
    return false;
  }
}

function playCombatBuffer(kind,volume,variation,delay=0){
  if(!sound||!prepareCombatAudio()||audioCtx.state!=='running')return;
  try{
    const source=audioCtx.createBufferSource(),voice=audioCtx.createGain();
    source.buffer=combatAudioCache[kind];
    source.playbackRate.value=1+(Math.random()*2-1)*variation;
    voice.gain.value=volume;
    source.connect(voice);voice.connect(combatAudioCache.bus);
    source.onended=()=>{source.disconnect();voice.disconnect();};
    source.start(audioCtx.currentTime+delay);
  }catch{}
}


const BOSS_INTRO_AUDIO={"dragon":"","doubao":""};
let bossMusicVoice=null,bossMusicGeneration=0;
const bossMusicBuffers=new Map();
function stopBossMusic(){bossMusicGeneration++;if(bossMusicVoice){try{bossMusicVoice.source.stop();bossMusicVoice.source.disconnect();bossMusicVoice.gain.disconnect();}catch{}bossMusicVoice=null;}}
async function playBossIntroMusic(kind){
 stopBossMusic();if(!sound||!BOSS_INTRO_AUDIO[kind]||!prepareCombatAudio())return false;
 const generation=bossMusicGeneration,context=audioCtx;
 try{
  let cache=bossMusicBuffers.get(kind);if(!cache||cache.context!==context){const raw=atob(BOSS_INTRO_AUDIO[kind]),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);cache={context,promise:context.decodeAudioData(bytes.buffer)};bossMusicBuffers.set(kind,cache);}
  const buffer=await cache.promise;if(generation!==bossMusicGeneration||!sound||audioCtx!==context||!player||state==='menu'||state==='lost')return false;
  const source=context.createBufferSource(),gain=context.createGain(),now=context.currentTime,duration=buffer.duration;source.buffer=buffer;source.connect(gain);gain.connect(context.destination);
  gain.gain.setValueAtTime(0,now);gain.gain.linearRampToValueAtTime(.38,now+.05);gain.gain.setValueAtTime(.38,now+Math.max(.05,duration-.5));gain.gain.linearRampToValueAtTime(0,now+duration);
  const voice={source,gain,kind};bossMusicVoice=voice;source.onended=()=>{try{source.disconnect();gain.disconnect();}catch{}if(bossMusicVoice===voice)bossMusicVoice=null;};source.start(now);return true;
 }catch{bossMusicBuffers.delete(kind);return false;}
}

function playAKShot(){playCombatBuffer('shot',.44,0);}
function playHeadshotSound(){playCombatBuffer('head',.47,0);}
function playHeadshotKillSound(){playCombatBuffer('headKill',.44,0);}

function showNotice(txt,duration=2.4){$('notice').textContent=txt;noticeTimer=duration;$('notice').classList.add('visible');}
function getBaseEnemyHealth(type){return type==='doubao'?2*encounterState.level40Health:type==='boss'?2000*Math.pow(1.5,bossState.count):type==='dog'?(difficulty==='easy'?18:24):type==='witch'?(difficulty==='easy'?6:difficulty==='hard'?10:8):(difficulty==='easy'?2:3);}
function createEnemy(type,x,z,id){
 if(!ENEMY_TYPES[type])type='milk';
 const dog=type==='dog',initialDelay=rnd(1.8,3),baseMaxHp=getBaseEnemyHealth(type),enemyScale=type==='doubao'?1:type==='boss'?getBossHealthScaling():getEnemyScaling(),maxHp=baseMaxHp*enemyScale,damageScale=getEnemyDamageScaling();
 return {x,z,type,y:ENEMY_TYPES[type].baseY,hp:maxHp,maxHp,baseMaxHp,enemyScale,damageScale,phase:rnd(0,6),attack:dog?initialDelay/2:type==='witch'?0:type==='boss'?1.4:(initialDelay+MILK_CHARGE)/MILK_ATTACK_RATE-MILK_CHARGE,flash:0,yaw:0,id,clawPhase:'idle',clawTimer:0,clawProgress:0,attackSide:1,strikeDone:false,casting:false,castPhase:'idle',castTimer:0,castProgress:0,castShots:0,supported:false,supportPulse:0,revivalAttempted:false,potionCooldown:0,potionPhase:'idle',potionTimer:0,potionProgress:0,potionKind:'damage',potionTarget:null,followTarget:null,followTargetId:null,bossPhase:'idle',bossProgress:0,bossTimer:0,bossAttackKind:'fireball',bossAttackYaw:0,bossTarget:null};
}
function rescaleEnemies(){
 const scale=getEnemyScaling(),damageScale=getEnemyDamageScaling();
 for(const enemy of enemies){
  if(!(enemy.hp>0))continue;
  const healthScale=enemy.type==='doubao'?1:enemyKind(enemy)==='boss'?getBossHealthScaling():scale,previous=enemy.enemyScale||1,ratio=healthScale/previous;
  enemy.baseMaxHp??=(enemy.maxHp??getBaseEnemyHealth(enemyKind(enemy)))/previous;
  enemy.hp*=ratio;enemy.maxHp=enemy.baseMaxHp*healthScale;enemy.enemyScale=healthScale;enemy.damageScale=damageScale;if(enemy.spawnLevel===40)encounterState.level40Health=enemy.maxHp;
 }
}
function randomEnemyType(){if(runProgress.level<5)return 'milk';const roll=Math.random()*(runProgress.level<10?80:110);return roll<40?'milk':roll<80?'dog':'witch';}
function getSpawnInterval(survivalTime=elapsed){return Math.max(.5,2.8*Math.pow(.86,Math.max(0,survivalTime)/30));}
function spawnPointHidden(type,x,z){
 const settings=ENEMY_TYPES[type],zones=type==='doubao'?DOUBAO_HIT_ZONES:type==='boss'?BOSS_HIT_ZONES:type==='dog'?DOG_HIT_ZONES:type==='witch'?WITCH_HIT_ZONES:ENEMY_HIT_ZONES;
 const height=settings.baseY+Math.max(...zones.map(zone=>zone[1]+zone[3])),extent=settings.radius+.4;
 const dx=x-player.x,dy=height*.5-player.y,dz=z-player.z,sy=Math.sin(player.yaw),cy=Math.cos(player.yaw),sp=Math.sin(player.pitch),cp=Math.cos(player.pitch);
 const depth=dx*sy*cp+dy*sp-dz*cy*cp,right=dx*cy+dz*sy,up=-dx*sy*sp+dy*cp+dz*cy*sp;
 const size=getGameSize(),tanY=Math.tan(38*Math.PI/180),tanX=tanY*size.width/Math.max(1,size.height),bound=Math.hypot(extent,height*.5);
 // A conservative full-body sphere keeps partially visible edge spawns out of the hidden tier.
 if(depth+bound<=0||Math.abs(right)>depth*tanX+bound*Math.hypot(1,tanX)||Math.abs(up)>depth*tanY+bound*Math.hypot(1,tanY))return true;
 // A chest ray alone would mistake low cover for hiding a visible head or flank.
 for(const point of [V(x,.15,z),V(x,height,z),V(x-extent,height*.5,z),V(x+extent,height*.5,z),V(x,height*.5,z-extent),V(x,height*.5,z+extent)]){
  const delta=sub(point,player),distance=length(delta);
  if(wallDistance(player,norm(delta))>distance-.05)return false;
 }
 return true;
}
function spawnEnemy(requestedType=null){
 if(state!=='playing'||!player||(!['boss','doubao'].includes(requestedType)&&getSmallEnemyCount()>=getEnemyCap()))return null;
 if(['boss','doubao'].includes(requestedType)&&enemies.some(enemy=>enemyKind(enemy)==='boss'&&enemy.hp>0))return null;
 const type=requestedType&&ENEMY_TYPES[requestedType]?requestedType:randomEnemyType(),radius=ENEMY_TYPES[type].radius,spots=currentMap.enemies,start=Math.floor(Math.random()*spots.length);
 let selected=null,fallback=null;
 for(let i=0;i<spots.length;i++){
  const [x,z]=spots[(start+i)%spots.length],distance=Math.hypot(x-player.x,z-player.z);
  if(distance<12||x-radius<-22.5||x+radius>22.5||z-radius<-28.5||z+radius>27.5||!canStand(x,z,radius,0))continue;
  if(enemies.some(other=>other.hp>0&&Math.hypot(x-other.x,z-other.z)<radius+enemySettings(other).radius+ENEMY_GAP))continue;
  if(spawnPointHidden(type,x,z)){selected=[x,z];break;}
  if(distance>=18&&!fallback)fallback=[x,z];
 }
 selected=selected||fallback;if(!selected)return null;
 const enemy=createEnemy(type,selected[0],selected[1],nextEnemyId++);enemies.push(enemy);spawned++;return enemy;
}
function resetBossState(){Object.assign(bossState,{spawned:false,defeated:false,enemyId:null,count:0,nextLevel:20});bossSpawnRetry=0;}
function trySpawnBoss(){
 if(state!=='playing'||!player||runProgress.level<bossState.nextLevel||(bossState.spawned&&!bossState.defeated))return null;
 const enemy=spawnEnemy('boss');if(!enemy)return null;
 bossState.spawned=true;bossState.defeated=false;bossState.enemyId=enemy.id;bossState.count++;bossState.nextLevel+=20;
 enemy.spawnLevel=bossState.nextLevel-20;if(enemy.spawnLevel===40)encounterState.level40Health=enemy.maxHp;showEncounter('小 Boss 来袭 · 火龙奶娃','三发扇形火球：蓄力0.9秒后射出；近距离扇形喷火：前摇1.1秒。利用掩体躲火球，看到地面扇形预警及时拉开距离。击败后掉落技能宝箱。');playBossIntroMusic('dragon');showNotice('小 Boss 来袭 · 火龙奶娃',3.5);tone(145,.35,'sawtooth',.035,-65);return enemy;
}
function updateEndlessSpawns(dt){
 if(state!=='playing'||dt<=0)return;
 const interval=getSpawnInterval();
 if(announceEnemyUnlock())return;
 if(runProgress.level>=50&&bossState.nextLevel>40&&!encounterState.doubaoSpawned&&(!bossState.spawned||bossState.defeated)){
  const enemy=spawnEnemy('doubao');if(!enemy){spawnTimer=.35;return;}
  playBossIntroMusic('doubao');encounterState.doubaoSpawned=true;Object.assign(bossState,{spawned:true,defeated:false,enemyId:enemy.id});enemy.laserCooldown=4;enemy.summonCooldown=8;enemy.attack=2;
  showEncounter('Lv 50 · 关卡大 Boss：豆包','生命：'+Math.round(enemy.maxHp)+'（40级火龙实际生命 '+Math.round(encounterState.level40Health)+' × 2）。眼部激光：前摇1秒，持续4秒，追踪你1秒前的位置，冷却20秒；普通攻击：4枚红色光球，伤害为奶蛙的1.5倍；召唤：在周围召唤4只刀盾狗。持续移动，避开激光并及时清理召唤物。');return;
 }
 // Each twenty-level milestone queues one boss; the previous boss must be defeated first.
 if(runProgress.level>=bossState.nextLevel&&(!bossState.spawned||bossState.defeated)){bossSpawnRetry=Math.max(0,bossSpawnRetry-dt);if(bossSpawnRetry<=1e-9){spawnTimer=trySpawnBoss()?interval:.35;bossSpawnRetry=.35;}return;}
 // A full arena or delayed frame never banks a burst of overdue spawns.
 if(getSmallEnemyCount()>=getEnemyCap()){spawnTimer=interval;return;}
 spawnTimer-=dt;if(spawnTimer>1e-9)return;
 spawnTimer=spawnEnemy()?interval:.35;
}
