  if(enemy.clawPhase==='windup'){
   enemy.clawPhase='strike';enemy.strikeDone=false;
   if(Math.hypot(player.x-enemy.x,player.z-enemy.z)<8)tone(480,.12,'triangle',.025,-350);
  }else if(enemy.clawPhase==='strike')enemy.clawPhase='recover';
