  enemy.attackYaw=enemy.yaw;enemy.attackSide=-(enemy.attackSide||1);enemy.clawPhase='windup';enemy.clawTimer=0;enemy.clawProgress=0;enemy.strikeDone=false;enemy.walking=false;
