  const theta=i/segments*Math.PI*2,cs=Math.cos(theta),sn=Math.sin(theta),p=j?b:a,r=j?rb:ra;
  const radial=[u[0]*cs+v[0]*sn,u[1]*cs+v[1]*sn,u[2]*cs+v[2]*sn];
